def verify():
    assert abs(math.sqrt(3) * 380 * 10 * 0.8 - 5265.4) < 0.1
    assert 4 * 500 * 0.01 * 1200 / (60 * 4) == 100
    assert abs(4200 / (2 * math.pi * 1200 / 60) - 33.42) < 0.01
    assert abs(4.44 * 60 * 100 * 0.01 - 266.4) < 1e-9 and abs(9000 / 9500 * 100 - 94.74) < 0.01
    assert abs(2 * 0.8 + 4 * 0.6 - 4) < 1e-12 and abs(1 / math.sqrt(3) - 0.577) < 0.001 and abs(300 / 3300 - 0.0909) < 1e-4
    assert abs((1800 - 1746) / 1800 - 0.03) < 1e-12 and abs(314 / math.pi - 99.95) < 0.01
    assert abs(2 * math.sqrt(2) * 100 / math.pi - 90.03) < 0.01 and abs(math.sin(math.radians(30)) / 0.5 - 1) < 1e-12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
